// narrows what was played without changing jobs.host_ids, so the recap, not
// host_ids, is the truth. The guards mirror runGroupQuery
// (internal/jobs/run_group.go): jsonb_typeof screens a JSON null, and
// pg_input_is_valid screens a bare host name before the uuid cast.
func (q *Queries) PlayedHosts(ctx context.Context, arg PlayedHostsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, playedHosts, arg.OrgID, arg.RunGroupID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var host_id uuid.UUID
		if err := rows.Scan(&host_id); err != nil {
			return nil, err
		}
		items = append(items, host_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resolvePendingFollowUps = `-- name: ResolvePendingFollowUps :execrows
UPDATE run_follow_ups
SET state = $1::text,
    reason = $2,
    host_ids = $3::uuid[],
    decided_at = $4::timestamptz,
    next_attempt_at = CASE WHEN $1::text = 'due' THEN $4::timestamptz END
WHERE org_id = $5 AND parent_group_id = $6 AND state = 'pending'
`

type ResolvePendingFollowUpsParams struct {
	State         string      `json:"state"`
	Reason        string      `json:"reason"`
	HostIds       []uuid.UUID `json:"host_ids"`
	Now           time.Time   `json:"now"`
	OrgID         uuid.UUID   `json:"org_id"`
	ParentGroupID uuid.UUID   `json:"parent_group_id"`
}

// The parent group has finished: every pending follow-up becomes due (and is
// handed the hosts it plays on) or is skipped with the reason. next_attempt_at
// starts at now for a due row, so the starter's index finds it.
func (q *Queries) ResolvePendingFollowUps(ctx context.Context, arg ResolvePendingFollowUpsParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolvePendingFollowUps,
		arg.State,
		arg.Reason,
		arg.HostIds,
		arg.Now,
		arg.OrgID,
		arg.ParentGroupID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const runGroupOutcome = `-- name: RunGroupOutcome :one
SELECT count(*) AS jobs,
       count(*) FILTER (WHERE status IN ('failed', 'error')) AS failed_or_error,
       count(*) FILTER (WHERE status = 'cancelled') AS cancelled
FROM jobs
WHERE org_id = $1 AND run_group_id = $2 AND kind = 'run'
  AND NOT (status = 'error' AND attempts = 1 AND error = $3::text)
`

type RunGroupOutcomeParams struct {
	OrgID          uuid.UUID `json:"org_id"`
	RunGroupID     uuid.UUID `json:"run_group_id"`
	WithdrawnError string    `json:"withdrawn_error"`
}

type RunGroupOutcomeRow struct {
	Jobs          int64 `json:"jobs"`
	FailedOrError int64 `json:"failed_or_error"`
	Cancelled     int64 `json:"cancelled"`
}

// The verdict of a finished run group, for the sweep: the job count, how many
// failed or errored and how many were cancelled. A job withdrawn at claim
// (internal/jobs/claim_withdrawn.go; withdrawn_error is
// jobs.WithdrawnAtClaimError) is left out as the finish report leaves it
// out: it ran nothing for an approval that no longer stands. A group of only
// such jobs counts zero jobs, so its follow-ups are skipped as never started.
func (q *Queries) RunGroupOutcome(ctx context.Context, arg RunGroupOutcomeParams) (RunGroupOutcomeRow, error) {
	row := q.db.QueryRow(ctx, runGroupOutcome, arg.OrgID, arg.RunGroupID, arg.WithdrawnError)
	var i RunGroupOutcomeRow
	err := row.Scan(&i.Jobs, &i.FailedOrError, &i.Cancelled)
	return i, err
}

const tryLockFollowUpTemplate = `-- name: TryLockFollowUpTemplate :one
SELECT pg_try_advisory_xact_lock(hashtext($1::text))::bool AS locked
`

// The starter's per-template start lock, taken in its batch transaction and
// held until the batch commits, after the enqueue it guards has committed.
// A second manager starting the same template in the meantime does not get
// it, and once it does, the active-run check sees the first one's run. The
// try variant never waits: two batches locking two templates in opposite
// orders cannot deadlock.
func (q *Queries) TryLockFollowUpTemplate(ctx context.Context, lockKey string) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockFollowUpTemplate, lockKey)
	var locked bool
	err := row.Scan(&locked)
	return locked, err
}
